-- Nearby Quest Tracking: keeps the quests nearest to the player in the
-- objective tracker and untracks the farthest ones as the player moves, among
-- the quests the scope allows ("anywhere", within "range", or in the current
-- zone), up to "count". A quest the player untracks stays untracked until they
-- change zone; one they track themselves is kept with "keepManual".
--
-- Files of this slice:
--   feature.lua  registration, schema and lifecycle (this file)
--   locales.lua  strings
--   data.lua     generated by `bun run instances`: the areas each instance's
--                quests are filed under in the quest log
--   ranking.lua  which quests should be tracked, closest first, and their order
--   watches.lua  the watch list: applying and ordering it, manual tracks, dismissals
--   refresh.lua  events and ticker, coalesced into one evaluation per frame

local _, ns = ...

local Tracking = ns:RegisterFeature("quests", "tracking", {
    page = "quests",
    order = 2,
    -- It takes over the objective tracker: the player opts in.
    enabledByDefault = false,
    settings = {
        {
            key = "scope",
            type = "dropdown",
            default = "anywhere",
            options = { "anywhere", "range", "zone" },
        },
        {
            key = "range",
            type = "slider",
            default = 500,
            min = 100,
            max = 2000,
            step = 50,
            requires = { scope = "range" },
        },
        { key = "count", type = "slider", default = 5, min = 1, max = 25, step = 1 },
        { key = "sort", type = "toggle", default = false },
        { key = "dungeons", type = "toggle", default = true },
        { key = "keepManual", type = "toggle", default = false },
    },
    presets = {
        minimal = { enabled = false },
        enhanced = { enabled = true },
    },
})

function Tracking:OnEnable()
    self.Refresh:Enable()
end

function Tracking:OnDisable()
    self.Refresh:Disable()
    self.Watches:Reset()
end

function Tracking:OnSettingChanged()
    self.Refresh:Request()
end
